  setInitialCredentials() {
    this.global.swalLoading("");
    this.header.append("Content-Type", "application/json");
    this.header.append("Authorization", "Bearer " + this.global.getSession());
    this.global.option = new RequestOptions({ headers: this.header });
    this.api.apiAccess()
      .subscribe(res => {
        this.global.swalClose()
        this.global.userroles = res.roles
        //console.log(res.roles)

        if (this.global.getvalidation().dp) {
          this.openDialogChangePassword(res.roles)
        } else {
          if (res.roles.length > 1) {
            this.openDialogopenroles(res.roles)
          } else {
            if (res.roles.includes('Employee')) {
              this.global.setrole('Employee')
              this.StudentRole = false;
              this.EmployeeRole = true;
              this.employeefunc()
            }
            else {
              this.global.setrole('Student')
              this.StudentRole = true;
              this.EmployeeRole = false;
              this.global.getallapi(0, '')
              this.id = this.global.requestid();
              this.displaysem = this.global.sydisplay;

            }
          }
        }
      }, Error => {
        //this.global.swalAlertError()
        this.global.logout()
      });
  }

