  private isApprovedBorrowRequest(request: any): boolean {
    if (!request) {
      return false;
    }

    const statusText = (request.borrowRequestStatus || request.BorrowRequestStatus || request.status || request.Status || '')
      .toString()
      .toLowerCase()
      .trim();

    if (statusText.includes('returned') || statusText.includes('rejected') || statusText.includes('cancelled') || statusText.includes('canceled')) {
      return false;
    }

    if (statusText === 'approved' || statusText.startsWith('approved')) {
      return true;
    }

    const approvalMark =
      request.isApproved ||
      request.IsApproved ||
      request.approved ||
      request.Approved ||
      request.approvedBy ||
      request.ApprovedBy ||
      request.approvedByName ||
      request.ApprovedByName ||
      request.approvedDate ||
      request.ApprovedDate ||
      request.approvedOn ||
      request.ApprovedOn ||
      request.approvedAt ||
      request.ApprovedAt ||
      request.dateApproved ||
      request.DateApproved;

    if (approvalMark) {
      return true;
    }

    const statusId = request.borrowRequestStatusID || request.BorrowRequestStatusID || request.statusID || request.statusId;
    if (typeof statusId === 'string') {
      return statusId.toLowerCase() === 'approved';
    }

    return false;
  }

