  async ngOnInit() {
    // Refresh guidance activity indicator once the portal loads.
    // global.loading is set asynchronously after studinfo is populated; we poll once briefly.
    setTimeout(() => this.refreshActivityIndicator(), 2000);
  }

  /** Call after each guidance action (book/reschedule/confirm) to update the activity indicator. */
  refreshActivityIndicator() {
    this.guidance.getPending().subscribe(a => {
      this.hasPendingAppointment = !!a;
      if (a) {
        if (a.status === 'Pending') { this.appointmentColorClass = 'appt-color-green'; }
        else if (a.status === 'Approved') { this.appointmentColorClass = 'appt-color-red'; }
        else if (a.status === 'Rescheduled') { this.appointmentColorClass = 'appt-color-yellow'; }
        else { this.appointmentColorClass = ''; }
      } else {
        this.appointmentColorClass = '';
      }
    }, () => { this.hasPendingAppointment = false; this.appointmentColorClass = ''; });
    this.guidance.getUnreadNotificationCount().subscribe(
      n => { this.hasUnreadNotification = n > 0; },
      () => { this.hasUnreadNotification = false; }
    );
  }


